async function main() {
  console.log('Seeding AIP recipes...');
  let created = 0;
  let skipped = 0;

  for (const recipe of recipes) {
    const existing = await prisma.recipe.findFirst({ where: { name: recipe.name } });
    if (existing) {
      console.log(`  Skipped (exists): ${recipe.name}`);
      skipped++;
      continue;
    }
    await prisma.recipe.create({ data: recipe });
    console.log(`  Created: ${recipe.name}`);
    created++;
  }

  console.log(`\nDone! Created ${created} recipes, skipped ${skipped} existing.`);
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect());
